import React, { useState } from 'react';
import api from './api.ts';
import { useNavigate } from 'react-router-dom';
import logoclara from './img/logo-clara.png';
import { useAuth } from './context/AuthContext.tsx';

const App: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [mostrarRecuperacao, setMostrarRecuperacao] = useState(false);
  const [emailRecuperacao, setEmailRecuperacao] = useState('');
  const navigate = useNavigate();
  const { login } = useAuth();
  const [loginError, serLoginError] = useState('');

  const handleLogin = async () => {
  try {
    setLoginError('');
    const res = await api.post('/api/login', { email, password });
    console.log('Resposta da API (login):', res.data);
    login(res.data);
    navigate('/dashboard');
  } catch (err) {
    setLoginError('Revise os dados de login e tente novamente.');
  }
  };


  const handleRecuperarSenha = async () => {
    try {
      const response = await fetch('http://localhost:3001/redefinir-senha', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: emailRecuperacao }),
      });

      const result = await response.json();
      if (response.ok) {
        alert('Email de recuperação enviado com sucesso!');
      } else {
        alert(result.message || 'Erro ao enviar recuperação.');
      }
    } catch (error) {
      alert('Erro na requisição.');
      console.error(error);
    }
  };

  return (
    <div className="p-login">
      <div className="p-img">
        <img alt="Logo da Valor Fiscal" src={logoclara} />
      </div>
      <div className="p-1">
        <h2 className="titulo-login">Painel do Licenciado</h2>

        {loginError }

        {!mostrarRecuperacao ? (
          <>
            <input type="email" placeholder="Email" className="input-login" onChange={e => setEmail(e.target.value)} />
            <input type="password" placeholder="Senha" className="input-login" onChange={e => setPassword(e.target.value)} />
            <button className="botao-login" onClick={handleLogin}>Login</button>
            <p><a href="#" onClick={() => setMostrarRecuperacao(true)}>Esqueceu sua senha?</a></p>
          </>
        ) : (
          <>
            <input type="email" placeholder="Digite seu email para recuperação" className="input-login" onChange={e => setEmailRecuperacao(e.target.value)} />
            <button className="botao-login" onClick={handleRecuperarSenha}>Enviar recuperação</button>
            <p><a href="#" onClick={() => setMostrarRecuperacao(false)}>Voltar para login</a></p>
          </>
        )}
      </div>
    </div>
  );



};

export default App;
